function(container, apiUrl, tables) {
  const tbody = container.querySelector('#inventory-tbody');
  const storeSelect = container.querySelector('#store-select');
  const categoryFilter = container.querySelector('#category-filter');
  const productNameSearch = container.querySelector('#product-name-search');
  const productCodeSearch = container.querySelector('#product-code-search');
  const stockStatusFilter = container.querySelector('#stock-status-filter');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');
  const noResults = container.querySelector('#no-results');

  let allInventoryData = [];
  let storeData = [];
  let productData = [];

  // エラー表示関数
  function showError(message) {
    errorText.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => {
      errorMessage.classList.add('hidden');
    }, 5000);
  }

  // エラー非表示関数
  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // 在庫状況を判定する関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return '不足';
    if (currentStock <= safetyStock) return '不足';
    if (currentStock > safetyStock * 2) return '過剰';
    return '適正';
  }

  // 在庫状況のスタイルを取得する関数
  function getStatusStyle(status) {
    switch (status) {
      case '不足':
        return 'background: rgba(255, 106, 0, 0.1); color: #ff6a00; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;';
      case '過剰':
        return 'background: rgba(255, 193, 7, 0.1); color: #ffc107; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;';
      case '適正':
        return 'background: rgba(40, 167, 69, 0.1); color: #28a745; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;';
      default:
        return 'padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;';
    }
  }

  // バリデーション関数
  function validateInputs() {
    hideError();

    const storeId = storeSelect.value;
    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    const productCode = productCodeSearch.value.trim();
    if (productCode && !/^[A-Za-z0-9]+$/.test(productCode)) {
      showError('商品コードは英数字で入力してください');
      return false;
    }

    const productName = productNameSearch.value.trim();
    if (productName && /<script|javascript:|on\w+=/i.test(productName)) {
      showError('商品名に不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // 在庫データを生成する関数（商品マスタと店舗マスタから）
  function generateInventoryData() {
    const inventoryData = [];

    productData.forEach(product => {
      storeData.forEach(store => {
        // ダミーの在庫データを生成
        const currentStock = Math.floor(Math.random() * 200);
        const safetyStock = Math.floor(Math.random() * 50) + 10;

        inventoryData.push({
          id: `${store.id}-${product.id}`,
          storeId: store.id,
          storeName: store.storeName || store.店舗名 || '',
          productId: product.id,
          productCode: product.productCode || product.商品コード || '',
          productName: product.productName || product.商品名 || '',
          currentStock: currentStock,
          safetyStock: safetyStock,
          unitPrice: product.unitPrice || product.単価 || 0,
          category: getProductCategory(product.productName || product.商品名 || ''),
          stockStatus: getStockStatus(currentStock, safetyStock)
        });
      });
    });

    return inventoryData;
  }

  // 商品名からカテゴリを推測する関数
  function getProductCategory(productName) {
    if (productName.includes('米') || productName.includes('パン') || productName.includes('肉') || productName.includes('魚')) {
      return '食品';
    } else if (productName.includes('洗剤') || productName.includes('石鹸') || productName.includes('タオル')) {
      return '日用品';
    } else if (productName.includes('シャツ') || productName.includes('パンツ') || productName.includes('靴')) {
      return '衣料品';
    } else if (productName.includes('テレビ') || productName.includes('冷蔵庫') || productName.includes('洗濯機')) {
      return '家電';
    }
    return '食品'; // デフォルト
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      noResults.classList.remove('hidden');
      return;
    }

    noResults.classList.add('hidden');

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}" style="border-bottom: 1px solid var(--border);">
        <td style="padding: 12px; color: var(--text); font-family: monospace;">${row.productCode || ''}</td>
        <td style="padding: 12px; color: var(--text);">${row.productName || ''}</td>
        <td style="padding: 12px; text-align: right; color: var(--text); font-weight: 500;">${row.currentStock || 0}</td>
        <td style="padding: 12px; text-align: right; color: var(--text);">${row.safetyStock || 0}</td>
        <td style="padding: 12px; text-align: center;">
          <span style="${getStatusStyle(row.stockStatus)}">${row.stockStatus || '適正'}</span>
        </td>
        <td style="padding: 12px; color: var(--text);">${row.category || ''}</td>
        <td style="padding: 12px; text-align: right; color: var(--text);">¥${(row.unitPrice || 0).toLocaleString()}</td>
        <td style="padding: 12px; text-align: center;">
          <button class="action-btn secondary" style="padding: 4px 8px; font-size: 12px;" onclick="window.showScreen('scr-1778591852463')">発注</button>
        </td>
      </tr>
    `).join('');
  }

  // 店舗選択肢を設定する関数
  function populateStoreOptions() {
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    storeData.forEach(store => {
      const option = document.createElement('option');
      option.value = store.id;
      option.textContent = `${store.storeCode || store.店舗コード || ''} - ${store.storeName || store.店舗名 || ''}`;
      storeSelect.appendChild(option);
    });
  }

  // フィルタリング関数
  function filterInventoryData() {
    if (!validateInputs()) return;

    const storeId = storeSelect.value;
    const category = categoryFilter.value;
    const productName = productNameSearch.value.trim().toLowerCase();
    const productCode = productCodeSearch.value.trim().toLowerCase();
    const stockStatus = stockStatusFilter.value;

    let filteredData = allInventoryData.filter(item => item.storeId === storeId);

    if (category) {
      filteredData = filteredData.filter(item => item.category === category);
    }

    if (productName) {
      filteredData = filteredData.filter(item => 
        item.productName.toLowerCase().includes(productName)
      );
    }

    if (productCode) {
      filteredData = filteredData.filter(item => 
        item.productCode.toLowerCase().includes(productCode)
      );
    }

    if (stockStatus) {
      filteredData = filteredData.filter(item => item.stockStatus === stockStatus);
    }

    renderRows(filteredData);
  }

  // CSVエクスポート関数
  function exportToCSV() {
    const storeId = storeSelect.value;
    if (!storeId) {
      showError('店舗を選択してからエクスポートしてください');
      return;
    }

    const currentData = allInventoryData.filter(item => item.storeId === storeId);

    if (currentData.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '現在在庫数', '安全在庫数', '在庫状況', 'カテゴリ', '単価'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map(row => [
        `"${row.productCode || ''}"`,
        `"${row.productName || ''}"`,
        row.currentStock || 0,
        row.safetyStock || 0,
        `"${row.stockStatus || ''}"`,
        `"${row.category || ''}"`,
        row.unitPrice || 0
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `inventory_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 検索条件クリア関数
  function clearSearchConditions() {
    storeSelect.value = '';
    categoryFilter.value = '';
    productNameSearch.value = '';
    productCodeSearch.value = '';
    stockStatusFilter.value = '';
    tbody.innerHTML = '';
    noResults.classList.add('hidden');
    hideError();
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 店舗データの読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores;
        populateStoreOptions();
      }

      // 商品データの読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products;
        allInventoryData = generateInventoryData();
      }
    } catch (error) {
      console.error('初期データの読み込みに失敗しました:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // イベントリスナーの設定
  container.querySelector('#btn-search').addEventListener('click', filterInventoryData);

  container.querySelector('#btn-clear').addEventListener('click', clearSearchConditions);

  container.querySelector('#btn-export').addEventListener('click', exportToCSV);

  // 店舗選択時の自動検索
  storeSelect.addEventListener('change', () => {
    if (storeSelect.value) {
      filterInventoryData();
    } else {
      tbody.innerHTML = '';
      noResults.classList.add('hidden');
    }
  });

  // Enterキーでの検索
  [productNameSearch, productCodeSearch].forEach(input => {
    input.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        filterInventoryData();
      }
    });
  });

  // 初期データ読み込み
  loadInitialData();
}
